// modules/services/kb.h — the embedded stock-item knowledge base (services.db, RCDATA SERVICES_KB).
// Generated by tools/services/genkb.py, which enforces rule 7 (every entry has a basis, every preset
// membership a pbasis, no unsourced numbers). Format: tools/services/README.md.
#pragma once

#include "core/sys/win_compat.h"
#include <map>
#include <string>
#include <vector>

namespace hx::services {

// Preset levels with KB membership. Default is not a KB level (it restores recorded values).
enum KbLevel { LV_BLOAT = 0, LV_STRIPPED = 1, LV_MINIMUM = 2, LV_COUNT = 3 };

struct KbEntry {
    std::wstring name, kind;           // kind: "svc" or "drv"
    std::vector<std::wstring> builds;  // e.g. {"19045"}
    std::wstring title, expl, ifOff, test;
    int lv[LV_COUNT] = {-1, -1, -1};   // target start type (3 or 4) where the entry joins that level
    std::wstring why[LV_COUNT];
    bool sysok = false, never = false;
    std::wstring basis, basisNote, pbasis, pbasisNote;
    int stock = -1;                    // Windows stock start type on the KB build; -1 = none
    int stockDelayed = 0;
    std::wstring stockBasis, stockNote;
    // Where the stock value comes from: "microsoft" (learn.microsoft.com pages), "table" (two agreeing third-party
    // tables), "disagree" (the tables disagree: stockNote says how, stock is -1), "" (measured, or none).
    std::wstring stockSrc;
    std::wstring hw;                   // hardware hint: class:<Name>, svc:<name>, self, vmguest, hvhost
    std::wstring contested;            // sources on both sides (URLs expanded), empty when not contested
    std::wstring sources;              // number sources (text, kind, ref) when the text has marked numbers

    // Cumulative membership: the target of the highest level at or below `level` that names one.
    int TargetAt(int level) const {
        int t = -1;
        for (int i = 0; i <= level && i < LV_COUNT; i++) if (lv[i] >= 0) t = lv[i];
        return t;
    }
    int JoinLevel() const { for (int i = 0; i < LV_COUNT; i++) if (lv[i] >= 0) return i; return -1; }
    const std::wstring& WhyAt(int level) const {
        static const std::wstring none;
        for (int i = level < LV_COUNT ? level : LV_COUNT - 1; i >= 0; i--) if (lv[i] >= 0) return why[i];
        return none;
    }
    bool ForBuild(const std::wstring& build) const {
        for (auto& b : builds) if (b == build) return true;
        return false;
    }
};

class Kb {
public:
    bool Parse(const std::string& utf8, std::wstring* err);
    const KbEntry* Find(const std::wstring& name) const;   // case-insensitive
    std::vector<KbEntry> entries;
    std::wstring version, build;   // V and B lines

private:
    std::map<std::wstring, size_t> index_;
};

bool LoadEmbeddedKb(Kb* kb, std::wstring* err);   // RCDATA SERVICES_KB from this exe
std::wstring LevelName(int level);                 // "Pure bloat removal", "Stripped", "Minimum"
// "folklore (repeated, no evidence)", ...; an owner-measured value with a condition is labelled by it (kb-audit
// svcdrv-stock M1: a value Hadron read on this PC is not "measured by Hadron's author").
std::wstring BasisLabel(const std::wstring& basis, const std::wstring& cond = L"");

}  // namespace hx::services
